<?php require 'config.php';requireLogin();if(empty($_SESSION['admin_access']))respond(['success'=>false,'message'=>'Admin access required.'],403);$columns=$pdo->query('DESCRIBE users')->fetchAll(PDO::FETCH_COLUMN);if(!in_array('status',$columns,true))respond(['success'=>false,'message'=>'Add a status column to the users table to use bans.'],422);$id=(int)(input()['id']??0);$s=$pdo->prepare("UPDATE users SET status=IF(status='banned','active','banned') WHERE id=?");$s->execute([$id]);respond(['success'=>true]);
